def safe_purge_collection(coll):
	"""
	Cannot remove documents from capped collections
	in later versions of MongoDB, so drop the
	collection instead.
	"""
	op = (
		drop_collection
		if coll.options().get('capped', False)
		else purge_collection
	)
	return op(coll)

