            Example:

            >>> salaries = household.members('salary', '2018-01')  # e.g. [2000, 1500, 0, 0, 0]
            >>> household.any(salaries >= 1800)
            >>> array([True])
        """
        import numpy as np

            if role is not None:
                indices = [i for i, m in enumerate(self.members) if m.role == role]
                if not indices:
                    return np.array([False])
