def tarjan_recursive(g):
        """ Returns the strongly connected components of the graph @g
            in a topological order.

                @g is the graph represented as a dictionary
                        { <vertex> : <successors of vertex> }.

            This function recurses --- large graphs may cause a stack
            overflow. """
            index_counter = [0]
            stack = []
            lowlink = {}
            index = {}
            on_stack = set()
            sccs = []

            def strongconnect(v):
                index[v] = lowlink[v] = index_counter[0]
                index_counter[0] += 1
                stack.append(v)
                on_stack.add(v)

                for w in g.get(v, []):
                    if w not in index:
                        strongconnect(w)
                        lowlink[v] = min(lowlink[v], lowlink[w])
                    elif w in on_stack:
                        lowlink[v] = min(lowlink[v], index[w])

                if lowlink[v] == index[v]:
                    component = []
                    while True:
                        w = stack.pop()
                        on_stack.remove(w)
                        component.append(w)
                        if w == v: break
                    sccs.append(component)

            for node in g:
                if node not in index:
                    strongconnect(node)

            return sccs

