def serializer_for(self, obj):
        """
            Searches for a serializer for the provided object
            Serializers will be  searched in this order;

            1-NULL serializer
            2-Default serializers, like primitives, arrays, string and some default types
            3-Custom registered types by user
            4-Global serializer if registered by user
            4-pickle serialization as a fallback

        :param obj: input object
        :return: Serializer
        """
            return self.get_serializer('null')

        # Check default serializers (primitives, lists, dicts, etc.)
        for default_type in self.default_serializers:
            if isinstance(obj, default_type):
                return self.get_serializer(default_type)

        # Check custom registered types
        obj_type = type(obj)
        if obj_type in self.custom_serializers:
            return self.custom_serializers[obj_type]

        # Check global serializer
        if self.global_serializer:
            return self.global_serializer

        # Fallback to pickle
        return self.get_serializer('pickle')

