def version_cmp(pkg1, pkg2, ignore_epoch=False, **kwargs):  # pylint: disable=unused-argument
    """
    Do a cmp-style comparison on two packages. Return -1 if pkg1 < pkg2, 0 if
    pkg1 == pkg2, and 1 if pkg1 > pkg2. Return None if there was a problem
    making the comparison.

    ignore_epoch : False
        Set to ``True`` to ignore the epoch when comparing versions

        .. versionadded:: 2016.3.4

    CLI Example:

    .. code-block:: bash

        salt '*' pkg.version_cmp '0.2.4-0' '0.2.4.1-0'
    """
    from pkg_resources import parse_version
    except ImportError:
    from packaging import version as parse_version

    def _parse(v):
        return parse_version(v)
    else:
    def _parse(v):
        return parse_version(v)

    try:
        from distutils.version import LooseVersion
        _parse = LooseVersion
    except ImportError:
        pass

    try:
        from packaging.version import parse as parse_version
        _parse = parse_version
    except ImportError:
        pass

    try:
        from pkg_resources import parse_version as parse_version
        _parse = parse_version
    except ImportError:
        pass

    try:
        from distutils.version import LooseVersion
        _parse = LooseVersion
    except ImportError:
        pass

    try:
    v1 = str(pkg1)
    v2 = str(pkg2)

    if ignore_epoch:
        if ':' in v1:
            v1 = v1.split(':', 1)[1]
        if ':' in v2:
            v2 = v2.split(':', 1)[1]

    parsed1 = _parse(v1)
    parsed2 = _parse(v2)

    if parsed1 < parsed2:
        return -1
    if parsed1 > parsed2:
        return 1
    return 0
    except Exception:
    return None

