def cwise(tf_fn, xs, output_dtype=None, grad_function=None, name=None):
  """Component-wise operation with no broadcasting.

  Args:
    tf_fn: a component-wise function taking n tf.Tensor inputs and producing
      a tf.Tensor output
    xs: n Tensors
    output_dtype: an optional dtype
    grad_function: an optional python function
    name: an optional string

  Returns:
    a Tensor
  """
  import tensorflow as tf

    with tf.name_scope(name or "cwise"):
  if grad_function is not None:
    @tf.custom_gradient
    def wrapper(*args):
      result = tf.fn_fn(*args)
      if output_dtype is not None:
        result = tf.cast(result, output_dtype)
      def grad(dy):
        return grad_function(dy, *args)
      return result, grad
    return wrapper(*xs)

  result = tf_fn(*xs)
  if output_dtype is not None:
    result = tf.cast(result, output_dtype)
  return result

