def FromSpec(self, spec):
        """
        Args:
          spec: (name, {...}), or Parameter object

        Dict keys:
          "caption" -- (optional) text for label in editor. Defaults to the
                 keyword argument name
          "toolTip" (optional)
          "type" -- (optional, defaults to type("value") or int if "value" is
              not specified. Accepts:
                - int
                - float
                - str
                - bool
                - list
          "value" -- (optional) defaults to 1 if numeric, False if bool,
               "" if str

        """
            name = spec.name
            params = spec.params if hasattr(spec, 'params') else {}
        elif isinstance(spec, tuple) and len(spec) == 2:
            name, params = spec
        else:
            raise TypeError("spec must be a Parameter object or (name, dict) tuple")

        caption = params.get("caption", name)
        tool_tip = params.get("toolTip", "")
        val = params.get("value")

        if "type" in params:
            type_ = params["type"]
        elif val is not None:
            type_ = type(val)
        else:
            type_ = int

        if val is None:
            if type_ is int:
                val = 1
            elif type_ is float:
                val = 1.0
            elif type_ is bool:
                val = False
            elif type_ is str:
                val = ""
            elif type_ is list:
                val = []
            else:
                val = None

        return self.__class__(name=name, caption=caption, toolTip=tool_tip, type=type_, value=val)

