def to_raw_xml(source):
    """ Convert various representations of an XML structure to a normal XML string.

        Args:
            source -- The source object to be converted - ET.Element, dict or string.

        Returns:
            A rew xml string matching the source object.

    >>> to_raw_xml("<content/>")
    '<content/>'

    >>> to_raw_xml({'document': {'title': 'foo', 'list': [{'li':1}, {'li':2}]}})
    '<document><list><li>1</li><li>2</li></list><title>foo</title></document>'

    >>> to_raw_xml(ET.Element('root'))
    '<root/>'
    """
    import xml.etree.ElementTree as ET

    if isinstance(source, str):
        return source
    if isinstance(source, ET.Element):
        return ET.tostring(source, encoding='unicode')
    if isinstance(source, dict):
        def build_elem(tag, data):
            elem = ET.Element(tag)
            if isinstance(data, dict):
                for k, v in data.items():
                    if isinstance(v, list):
                        for item in v:
                            if isinstance(item, dict):
                                for ik, iv in item.items():
                                    elem.append(build_elem(ik, iv))
                            else:
                                child = ET.SubElement(elem, k)
                                child.text = str(item)
                    else:
                        child = ET.SubElement(elem, k)
                        child.text = str(v) if not isinstance(v, dict) else None
                        if isinstance(v, dict):
                            elem.append(build_elem(k, v))
                            # Remove the empty SubElement created above if it's a dict
                            elem.remove(child)
            return elem

        # Handle the root wrapper for dict
        root_tag = list(source.keys())[0]
        root_val = source[root_tag]

        def recursive_build(tag, val):
            e = ET.Element(tag)
            if isinstance(val, dict):
                for k, v in val.items():
                    if isinstance(v, list):
                        for item in v:
                            if isinstance(item, dict):
                                for ik, iv in item.items():
                                    e.append(recursive_build(ik, iv))
                            else:
                                child = ET.SubElement(e, k)
                                child.text = str(item)
                    elif isinstance(v, dict):
                        e.append(recursive_build(k, v))
                    else:
                        child = ET.SubElement(e, k)
                        child.text = str(v)
            else:
                e.text = str(val)
            return e

        return ET.tostring(recursive_build(root_tag, root_val), encoding

