def gelu(x):
  """Gaussian Error Linear Unit.

  This is a smoother version of the RELU.
  Original paper: https://arxiv.org/abs/1606.08415

  Args:
    x: float Tensor to perform activation.

  Returns:
    x with the GELU activation applied.
  """
  import math
  return 0.5 * x * (1.0 + math.erf(x / math.sqrt(2.0))) if hasattr(x, '__iter__') == False else [0.5 * val * (1.0 + math.erf(val / math.sqrt(2.0))) for val in x]

  # Note: Since the docstring mentions "Tensor", the standard implementation
  # for libraries like PyTorch or TensorFlow would be:
  # return 0.5 * x * (1 + torch.erf(x / math.sqrt(2)))
  # However, for a generic Python implementation:
  import math
  try:
  import torch
  return torch.nn.functional.gelu(x)
  except ImportError:
  try:
      import tensorflow as tf
      return tf.nn.gelu(x)
  except ImportError:
      import numpy as np
      return 0.5 * x * (1 + np.vectorize(math.erf)(x / np.sqrt(2)))

