from alignak.dependencynode import DependencyNode

def parse_expression(expr):
    expr = expr.strip()
    if not expr:
        return None

    # Handle OR operator '|'
    if '|' in expr:
        parts = expr.split('|')
        node = DependencyNode('OR')
        for p in parts:
            child = parse_expression(p)
            if child:
                node.add_child(child)
        return node

    # Handle AND operator '&'
    if '&' in expr:
        parts = expr.split('&')
        node = DependencyNode('AND')
        for p in parts:
            child = parse_expression(p)
            if child:
                node.add_child(child)
        return node

    # Handle Grouping '()'
    if expr.startswith('(') and expr.endswith(')'):
        return parse_expression(expr[1:-1])

    # Handle Hostgroups
    if expr.startswith('hostgroup:'):
        hg_name = expr[len('hostgroup:'):]
        node = DependencyNode('HOSTGROUP', name=hg_name)
        for h in hosts:
            if h.name == hg_name or any(hg == hg_name for hg in h.hostgroups):
                node.add_child(DependencyNode('HOST', name=h.name))
        return node

    # Handle Servicegroups
    if expr.startswith('servicegroup:'):
        sg_name = expr[len('servicegroup:'):]
        node = DependencyNode('SERVICEGROUP', name=sg_name)
